insert into public.prompts(title,category,prompt_text,output_example,is_free,sort_order) values
('Plan a focused study session','Study','Act as a supportive study coach. I need to learn [TOPIC] for [EXAM/GOAL] and have [TIME] available. Ask what I know, then create a realistic session plan with focus blocks, active recall, breaks, and a 5-question self-check.','A realistic 60-minute plan with recall questions.',true,1),
('Write a clear client proposal','Freelancing','Draft a concise proposal for [CLIENT] who needs [PROJECT]. My experience is [EXPERIENCE], timeline [TIMELINE], budget [BUDGET]. Include scope, deliverables, timeline, price, and a next step. Do not invent credentials or promise results.','A clear client proposal with scope and price.',true,2),
('Turn an idea into a week of posts','Content','I create [NICHE] content for [AUDIENCE] on [PLATFORM]. Turn [IDEA] into five distinct posts with a strong first line, useful takeaway, and natural closing question. Tone: [TONE]. Avoid clichés and repeated angles.','Five varied post ideas with hooks.',true,3),
('Make a practical weekly plan','Productivity','Help plan my week. Priorities: [PRIORITIES]. Fixed commitments: [COMMITMENTS]. Flexible hours: [HOURS]. Ask one useful question if needed, then make a realistic schedule with focus time, buffer, and rest. Flag anything that will not fit.','A balanced weekly outline that respects capacity.',true,4),
('Prepare for an interview','Career','Help me prepare for a [ROLE] interview at a [COMPANY TYPE] company. My experience: [BACKGROUND]. Identify likely skills, then ask five practice questions one at a time. Give concise feedback after each answer. Never invent experience.','Tailored practice questions and feedback.',true,5),
('Find the right freelance rate','Freelancing','Help price a [PROJECT] for [CLIENT TYPE]. Consider scope, revisions, research, meetings, timeline, and my experience [LEVEL]. Ask for missing context and offer three transparent pricing options with trade-offs. Do not guarantee acceptance.','Three pricing options with scope boundaries.',false,6),
('Write a thoughtful cold email','Freelancing','Draft a short, personal outreach email to [PERSON] at [COMPANY] about [RELEVANT IDEA]. Use one specific reason for reaching out, one useful observation, and a low-pressure next step. Under 130 words.','A direct, personalized outreach message.',false,7),
('Create a simple project brief','Freelancing','Turn this client request into a project brief: [REQUEST]. Include objective, audience, deliverables, exclusions, milestones, approvals, and open questions. Mark assumptions clearly.','A structured one-page brief.',false,8),
('Build a client onboarding flow','Freelancing','Design a simple onboarding process for a [SERVICE] client. Include welcome message, information to collect, kickoff agenda, access checklist, and first-week expectations. Keep it warm and concise.','A usable onboarding checklist and welcome email.',false,9),
('Turn feedback into themes','Business','Group this customer feedback into themes: [FEEDBACK]. Show frequency, representative paraphrase, severity, and a follow-up question for each theme. Preserve uncertainty and do not infer demographics.','A prioritized table of feedback themes.',false,10),
('Map a competitor landscape','Business','Compare [COMPANY] with [COMPETITORS] for [AUDIENCE]. Make a framework for positioning, pricing, strengths, gaps, and evidence to verify. Separate known facts from hypotheses; ask me for source links if needed.','A comparison matrix with evidence gaps.',false,11),
('Outline a landing page','Marketing','Outline a landing page for [OFFER] aimed at [AUDIENCE]. Include hero, problem, benefits, proof placeholders, process, pricing, FAQs, and CTA. Use plain language and avoid unsupported claims.','A conversion-focused page outline.',false,12),
('Generate campaign angles','Marketing','Create six campaign angles for [PRODUCT] and [AUDIENCE]. Each should include audience tension, core message, example headline, and channel fit. Avoid false urgency and claims without evidence.','Six distinct, testable campaign directions.',false,13),
('Repurpose a long video','Content','Repurpose this video transcript [TRANSCRIPT] into a short post, a carousel outline, and three short-video hooks. Retain key meaning, cite uncertainty, and do not invent quotes.','A compact multi-channel content set.',false,14),
('Write a short video script','Content','Write a 30-second video script about [TOPIC] for [AUDIENCE]. Include spoken lines, simple visual notes, a useful takeaway, and a natural ending. Tone [TONE], no clickbait.','A concise shot-by-shot script.',false,15),
('Create a revision plan','Study','Build a revision plan for [SUBJECT] across [DAYS] days. Topics and confidence: [LIST]. Include retrieval practice, spaced review, and short checks. Leave one buffer session.','A realistic plan with spaced practice.',false,16),
('Explain a concept simply','Study','Explain [CONCEPT] to a learner at [LEVEL]. Start with a plain-language explanation, give a concrete example, note a common misconception, then ask me one check-for-understanding question.','A clear explanation with an example.',false,17),
('Improve a resume bullet','Career','Improve this resume bullet [BULLET] for a [ROLE] application. Ask for missing facts; preserve truth. Offer three versions emphasizing scope, action, and measurable impact only where evidence is provided.','Three truthful, stronger bullet options.',false,18),
('Practice a salary conversation','Career','Help me prepare to discuss compensation for [ROLE]. Context: [OFFER/REVIEW], priorities: [PRIORITIES]. Draft a calm opening, evidence points, questions, and responses to likely pushback. Do not assume market numbers; identify what to research.','A negotiation preparation outline.',false,19),
('Plan a focused workday','Productivity','Plan a day with [TASKS], meetings [MEETINGS], and work hours [HOURS]. Rank tasks by impact and urgency, include focus blocks and breaks, and identify one item to defer if the day becomes full.','A realistic day plan with a fallback.',false,20);
insert into public.prompts(title,category,prompt_text,output_example,is_free,is_bonus,sort_order) values
('Turn a goal into a 30-day sprint','Planning','Help me turn [GOAL] into a 30-day sprint. Ask about available time and constraints. Then define a measurable outcome, weekly milestones, a small daily action, a review ritual, and a fallback plan for disrupted days. Keep the scope realistic.','A four-week sprint plan with review points.',false,true,301),
('Design a reusable AI workflow','Productivity','Design a repeatable AI-assisted workflow for [TASK]. Map inputs, preparation, prompt steps, human review, quality checks, and final output. Identify sensitive information I should not paste into an AI tool.','A workflow with human review and privacy checks.',false,true,302),
('Turn a meeting into action items','Work','Convert these meeting notes [NOTES] into decisions, owners, due dates, open questions, and a concise follow-up email. Mark missing owners or dates as unknown instead of guessing.','A clear action list and follow-up draft.',false,true,303),
('Build a decision memo','Business','Help me compare [OPTIONS] for [DECISION]. Ask for constraints if needed. Produce a short memo with criteria, evidence, trade-offs, risks, reversible next step, and what evidence could change the recommendation.','A concise decision memo with transparent trade-offs.',false,true,304),
('Create a personal learning system','Study','Build a learning system for [SKILL] over [TIMEFRAME]. Include a weekly practice rhythm, spaced review, small projects, feedback sources, and a way to track progress without over-measuring. Adapt to my available time [HOURS].','A sustainable weekly learning routine.',false,true,305)
