create extension if not exists pgcrypto;
create table if not exists public.prompts (id uuid primary key default gen_random_uuid(), title text not null, category text not null, prompt_text text not null, output_example text, is_free boolean not null default false, is_bonus boolean not null default false, sort_order int not null default 0, created_at timestamptz not null default now());
alter table public.prompts add column if not exists is_bonus boolean not null default false;
create table if not exists public.purchases (id uuid primary key default gen_random_uuid(), email text, razorpay_payment_id text unique, razorpay_order_id text not null unique, amount int not null default 19900, product text not null default 'library', status text not null default 'created', access_token uuid unique default gen_random_uuid(), utm_source text, utm_campaign text, utm_medium text, created_at timestamptz not null default now());
alter table public.purchases add column if not exists product text not null default 'library';
create table if not exists public.subscribers (id uuid primary key default gen_random_uuid(), email text not null unique, source text, utm_source text, utm_campaign text, created_at timestamptz not null default now());
create table if not exists public.visits (id uuid primary key default gen_random_uuid(), session_id text not null, utm_source text, utm_campaign text, created_at timestamptz not null default now());
create table if not exists public.rate_limits (bucket text not null, subject text not null, window_start timestamptz not null, hits int not null default 1, primary key(bucket,subject,window_start));
create or replace function public.hit_rate_limit(p_bucket text,p_subject text,p_max int,p_window_seconds int) returns boolean language plpgsql security definer set search_path=public as $$ declare n int; w timestamptz; begin w:=to_timestamp(floor(extract(epoch from now())/p_window_seconds)*p_window_seconds); insert into rate_limits(bucket,subject,window_start,hits) values(p_bucket,p_subject,w,1) on conflict(bucket,subject,window_start) do update set hits=rate_limits.hits+1 returning hits into n; return n<=p_max; end $$;
revoke execute on function public.hit_rate_limit(text,text,int,int) from public, anon, authenticated;
grant execute on function public.hit_rate_limit(text,text,int,int) to service_role;
create index if not exists purchases_email_idx on public.purchases(email);
create index if not exists purchases_payment_idx on public.purchases(razorpay_payment_id);
create index if not exists purchases_order_idx on public.purchases(razorpay_order_id);
create unique index if not exists visits_session_idx on public.visits(session_id);
create unique index if not exists prompts_title_idx on public.prompts(title);
alter table public.prompts enable row level security; alter table public.purchases enable row level security; alter table public.subscribers enable row level security; alter table public.visits enable row level security;
alter table public.rate_limits enable row level security;
drop policy if exists "Public can read free prompts" on public.prompts;
create policy "Public can read free prompts" on public.prompts for select to anon, authenticated using (is_free = true);
revoke all on public.purchases, public.subscribers, public.visits from anon, authenticated;
grant select on public.prompts to anon, authenticated;
on conflict do nothing;
